def transform(grid):
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    centers=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if grid[r][c]==0 and grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr:
                for x in range(min(c,cc)+2,max(c,cc)) :
                    if grid[r][x]==0: out[r][x]=1
            if c==cc:
                for y in range(min(r,rr)+2,max(r,rr)) :
                    if grid[y][c]==0: out[y][c]=1
    return out
